    map['client_contact_person'] = Variable<String>(clientContactPerson);
    map['client_contact_number'] = Variable<String>(clientContactNumber);
    map['client_email'] = Variable<String>(clientEmail);
    map['representative_name'] = Variable<String>(representativeName);
