    map['batch_number'] = Variable<String>(batchNumber);
    if (!nullToAbsent || bestBefore != null) {
      map['best_before'] = Variable<DateTime>(bestBefore);
    }
    if (!nullToAbsent || traySizeId != null) {
      map['tray_size_id'] = Variable<int>(traySizeId);
    }
    if (!nullToAbsent || declaredSizeId != null) {
      map['declared_size_id'] = Variable<int>(declaredSizeId);
    }
    if (!nullToAbsent || declaredGradeId != null) {
      map['declared_grade_id'] = Variable<int>(declaredGradeId);
    }
    if (!nullToAbsent || sampleSize != null) {
      map['sample_size'] = Variable<int>(sampleSize);
    }
    map['pasteurised_present'] = Variable<bool>(pasteurisedPresent);
    map['haugh_not_required'] = Variable<bool>(haughNotRequired);
    if (!nullToAbsent || determinedGradeId != null) {
      map['determined_grade_id'] = Variable<int>(determinedGradeId);
    }
    map['grade_overridden'] = Variable<bool>(gradeOverridden);
    map['override_reason'] = Variable<String>(overrideReason);
    map['general_comments'] = Variable<String>(generalComments);
    map['non_conformance_comments'] = Variable<String>(nonConformanceComments);
    map['failed_requirement_ids'] = Variable<String>(failedRequirementIds);
    map['restricted_particular_ids'] =
