  final int eggNumber;
  final double? massG;
  final int? sizeId;
  final int? gradeId;
  final double? albumenHeightMm;
  final double? haughUnit;

  /// Comma-separated deviation ids ticked on this egg.
  final String deviationIds;
  const EggSample(
      {required this.id,
      required this.inspectionUuid,
      required this.eggNumber,
