    map['egg_number'] = Variable<int>(eggNumber);
    if (!nullToAbsent || massG != null) {
      map['mass_g'] = Variable<double>(massG);
    }
    if (!nullToAbsent || sizeId != null) {
      map['size_id'] = Variable<int>(sizeId);
    }
    if (!nullToAbsent || gradeId != null) {
      map['grade_id'] = Variable<int>(gradeId);
    }
    if (!nullToAbsent || albumenHeightMm != null) {
      map['albumen_height_mm'] = Variable<double>(albumenHeightMm);
    }
    if (!nullToAbsent || haughUnit != null) {
      map['haugh_unit'] = Variable<double>(haughUnit);
    }
    map['deviation_ids'] = Variable<String>(deviationIds);
    return map;
  }

  EggSamplesCompanion toCompanion(bool nullToAbsent) {
    return EggSamplesCompanion(
      id: Value(id),
      inspectionUuid: Value(inspectionUuid),
      eggNumber: Value(eggNumber),
      massG:
          massG == null && nullToAbsent ? const Value.absent() : Value(massG),
      sizeId:
          sizeId == null && nullToAbsent ? const Value.absent() : Value(sizeId),
      gradeId: gradeId == null && nullToAbsent
