      remarkIds: serializer.fromJson<String>(json['remarkIds']),
      additionalRemarks: serializer.fromJson<String>(json['additionalRemarks']),
      clientName: serializer.fromJson<String>(json['clientName']),
      producerSupplier: serializer.fromJson<String>(json['producerSupplier']),
      latitude: serializer.fromJson<double?>(json['latitude']),
      longitude: serializer.fromJson<double?>(json['longitude']),
      isUploaded: serializer.fromJson<bool>(json['isUploaded']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      inspectorUsername:
          serializer.fromJson<String?>(json['inspectorUsername']),
    );
  }
