            inspectionUuid.present ? inspectionUuid.value : this.inspectionUuid,
        labellingPart: labellingPart ?? this.labellingPart,
        qualityPart: qualityPart ?? this.qualityPart,
        labelCorrectBy:
            labelCorrectBy.present ? labelCorrectBy.value : this.labelCorrectBy,
        qualityCorrectBy: qualityCorrectBy.present
            ? qualityCorrectBy.value
            : this.qualityCorrectBy,
        status: status ?? this.status,
        issuedAt: issuedAt ?? this.issuedAt,
        directionNumber: directionNumber ?? this.directionNumber,
        quantityRemoved: quantityRemoved.present
            ? quantityRemoved.value
            : this.quantityRemoved,
        remarkIds: remarkIds ?? this.remarkIds,
        additionalRemarks: additionalRemarks ?? this.additionalRemarks,
        clientName: clientName ?? this.clientName,
        producerSupplier: producerSupplier ?? this.producerSupplier,
        latitude: latitude.present ? latitude.value : this.latitude,
        longitude: longitude.present ? longitude.value : this.longitude,
        isUploaded: isUploaded ?? this.isUploaded,
        updatedAt: updatedAt ?? this.updatedAt,
